(() => {
  const ID = 'color-pulse';
  const shell = () => window.TelePlayGameShell;
  const tg = window.Telegram?.WebApp;
  let screen, orb, hint, scoreEl, round = 0, score = 0, target = 'cyan', running = false, paused = false, callbacks = {}, initialized = false, timer = 0;
  const COLORS = ['cyan','pink','gold'];
  const haptic = type => { try { tg?.HapticFeedback?.impactOccurred(type); } catch (_) {} };
  function next() { target = COLORS[Math.floor(Math.random() * COLORS.length)]; orb.className = `pulse-orb ${target} ${['top','right','bottom','left'][Math.floor(Math.random() * 4)]}`; hint.textContent = `Центр: ${target === 'cyan' ? 'бирюзовый' : target === 'pink' ? 'розовый' : 'золотой'} · тапни нужный цвет`; clearTimeout(timer); timer = setTimeout(() => miss(), 1250); }
  function tap(color) { if (!running || paused) return; if (color === target) { clearTimeout(timer); score += 30 + round * 4; round += 1; hint.textContent = 'Совпадение!'; haptic('light'); if (round >= 12) finish(true); else next(); } else miss(); scoreEl.textContent = score; }
  function miss() { if (!running) return; clearTimeout(timer); score = Math.max(0, score - 20); round += 1; hint.textContent = 'Импульс не совпал'; haptic('heavy'); if (round >= 12) finish(false); else next(); scoreEl.textContent = score; }
  function finish(success) { if (!running) return; running = false; clearTimeout(timer); const previous = shell().getStats(ID), result = shell().saveResult(ID, score, { bestRound: Math.max(previous.bestRound || 0, round), lastResult: { score, rounds: round } }), reward = Math.max(1, Math.floor(score / 100)); window.TelePlayCore?.RewardManager?.award(ID, { coins: reward, score, metadata: { transactionId: `game:${ID}:run:${Date.now()}`, rounds: round } }); shell().emit('color_pulse_finished', { gameId: ID, score, rounds: round, reward }); shell().emit('game_finished', { gameId: ID, score, reward, rounds: round, victory: success }); shell().ResultScreen.show(screen.querySelector('[data-pulse-result]'), { score, bestScore: result.bestScore, reward, newRecord: result.newRecord, title: success ? 'Ритм<br>пойман!' : 'Импульс<br>сорван', details: { rounds: `${round} / 12`, matches: Math.max(0, Math.floor(score / 30)) } }); screen.querySelector('[data-pulse-result]').hidden = false; }
  function start() { running = true; paused = false; round = 0; score = 0; screen.querySelector('[data-pulse-start]').hidden = true; screen.querySelector('[data-pulse-result]').hidden = true; screen.querySelector('[data-pulse-pause]').textContent = 'Ⅱ'; scoreEl.textContent = '0'; shell().emit('color_pulse_started', { gameId: ID }); shell().emit('game_started', { gameId: ID }); next(); haptic('light'); }
  function open(options = {}) { callbacks = options; screen.hidden = false; screen.querySelector('[data-pulse-start]').hidden = false; screen.querySelector('[data-pulse-result]').hidden = true; const stats = shell().getStats(ID); screen.querySelector('[data-pulse-menu-best]').textContent = Number(stats.bestScore || 0).toLocaleString('ru-RU'); try { tg?.requestFullscreen?.(); tg?.disableVerticalSwipes?.(); } catch (_) {} }
  function hide() { running = false; clearTimeout(timer); screen.hidden = true; try { tg?.enableVerticalSwipes?.(); tg?.exitFullscreen?.(); } catch (_) {} }
  function close() { hide(); callbacks.onHome?.(); }
  function pause() { if (!running) return; paused = !paused; screen.querySelector('[data-pulse-pause]').textContent = paused ? '▶' : 'Ⅱ'; if (!paused) next(); else clearTimeout(timer); shell().emit(paused ? 'game_paused' : 'game_resumed', { gameId: ID }); }
  function init() { if (initialized) return; initialized = true; screen = document.getElementById('colorPulseScreen'); screen.innerHTML = `<div class="color-pulse-inner"><header class="color-pulse-hud"><button class="icon-button" data-pulse-close aria-label="На главную">×</button><div class="color-pulse-brand"><small>TELEPLAY · РЕАКЦИЯ</small><b>Color Pulse</b></div><div class="color-pulse-stat"><small>СЧЁТ</small><b data-pulse-score>0</b></div><button class="icon-button" data-pulse-pause aria-label="Пауза">Ⅱ</button></header><div class="pulse-arena"><span class="pulse-ring"></span><span class="pulse-core">СИНХРОН</span><span class="pulse-orb cyan top" data-pulse-orb></span></div><p class="pulse-hint" data-pulse-hint>Совмести центр и внешний импульс</p><div class="pulse-controls"><button type="button" data-pulse-cyan>CYAN</button><button type="button" data-pulse-pink>PINK</button><button type="button" data-pulse-gold>GOLD</button></div></div><div class="start-panel" data-pulse-start><span class="panel-kicker">TELEPLAY · РЕАКЦИЯ</span><h2>Color<br>Pulse</h2><p>Следи за центром и периферией.<br>Проходи только через свой цвет.</p><button class="play-button large" data-pulse-start-button>Начать импульс</button><div class="record">Лучший результат: <b data-pulse-menu-best>0</b></div></div><div class="start-panel result-panel" data-pulse-result hidden><span class="panel-kicker" data-result="kicker">ИМПУЛЬС ЗАВЕРШЁН</span><h2 data-result="title">Ритм<br>пойман!</h2><div class="result-score"><small>РЕЗУЛЬТАТ</small><b data-result="score">0</b></div><div class="result-details"><span>Лучший результат <b data-result="best">0</b></span><span>Получено <b data-result="reward">+0 🪙</b></span><span>Раунды <b data-result="rounds">0 / 12</b></span><span>Совпадения <b data-result="matches">0</b></span></div><button class="play-button large" data-pulse-replay>Новый ритм</button><button class="text-button" data-pulse-home>На главную</button></div>`; orb = screen.querySelector('[data-pulse-orb]'); hint = screen.querySelector('[data-pulse-hint]'); scoreEl = screen.querySelector('[data-pulse-score]'); screen.querySelector('[data-pulse-cyan]').addEventListener('click', () => tap('cyan')); screen.querySelector('[data-pulse-pink]').addEventListener('click', () => tap('pink')); screen.querySelector('[data-pulse-gold]').addEventListener('click', () => tap('gold')); screen.querySelector('[data-pulse-start-button]').addEventListener('click', start); screen.querySelector('[data-pulse-replay]').addEventListener('click', start); screen.querySelector('[data-pulse-home]').addEventListener('click', close); screen.querySelector('[data-pulse-close]').addEventListener('click', close); screen.querySelector('[data-pulse-pause]').addEventListener('click', pause); document.addEventListener('visibilitychange', () => { if (document.hidden && !screen.hidden && running && !paused) pause(); }); }
  window.ColorPulseGame = { init, open, hide, close, start, restart: start, pause, resume: () => { if (paused) pause(); }, destroy: hide };
  document.readyState === 'loading' ? document.addEventListener('DOMContentLoaded', init) : init();
})();
